import{_ as a,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"VBench-2.0: Advancing Video Generation Benchmark Suite for Intrinsic Faithfulness","description":"","frontmatter":{"title":"VBench-2.0: Advancing Video Generation Benchmark Suite for Intrinsic Faithfulness","arxiv":"2503.21755","date":"2025-03-27","authors":"Dian Zheng, Ziqi Huang, Hongbo Liu, Kai Zou, Yinan He, Fan Zhang, Lulu Gu, Yuanhan Zhang, Jingwen He, et al.","categories":"cs.CV","topics":"后训练与强化学习, 评测基准, 内在真实性","outline":[2,2]},"headers":[],"relativePath":"papers/2503.21755.md","filePath":"papers/2503.21755.md","lastUpdated":null}'),p={name:"papers/2503.21755.md"};function i(l,s,r,m,o,c){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="vbench-2-0-advancing-video-generation-benchmark-suite-for-intrinsic-faithfulness" tabindex="-1">VBench-2.0: Advancing Video Generation Benchmark Suite for Intrinsic Faithfulness <a class="header-anchor" href="#vbench-2-0-advancing-video-generation-benchmark-suite-for-intrinsic-faithfulness" aria-label="Permalink to &quot;VBench-2.0: Advancing Video Generation Benchmark Suite for Intrinsic Faithfulness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.21755" target="_blank" rel="noreferrer">2503.21755</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-27</td></tr><tr><td><strong>作者</strong></td><td>Dian Zheng, Ziqi Huang, Hongbo Liu, Kai Zou, Yinan He, Fan Zhang, Lulu Gu, Yuanhan Zhang, Jingwen He, Wei-Shi Zheng, Yu Qiao, Ziwei Liu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把视频评测从「看起来像真的」推进到「本质上是真的」，用五大类 18 个细粒度维度、通才 VLM/LLM 加专才异常检测器的混合流水线，去测物理、常识、人体结构与复杂指令遵循。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/post-training-rl">后训练与强化学习</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv 的 HTML 全文只有 <strong>v2</strong>（2025-08-20 修订，v1 提交于 2025-03-27），本文按 v2 撰写。前两位作者贡献相同。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>第一代视频评测（VBench 及同类）测的是逐帧美学、帧间平滑度、简单文本对齐——作者把这些统称为<strong>表层真实性</strong>（superficial faithfulness），即「这段视频看起来像不像真的」。这套指标在 2023 年是合适的，因为那时的模型连稳定的两秒片段都难以生成。但到了 Sora、Kling、Gen-3、HunyuanVideo、Veo 2 这一代，表层指标大面积饱和：主体一致性、背景一致性、运动平滑度这些维度上，几个头部模型的分数已经挤在小数点后一两位的范围里，失去了区分度。</p><p>问题是，指标饱和不等于问题解决。这些模型仍然会生成手指数量错误的人、切了刀但没被切开的物体、被要求变色却全程不变的树叶。作者把这类缺陷归为<strong>内在真实性</strong>（intrinsic faithfulness）：视频是否遵守物理定律、常识推理、解剖正确性与组合完整性。这个概念区分之所以重要，是因为它决定了下一代模型该往哪个方向优化——如果社区继续用饱和的指标做 checkpoint 选择和后训练奖励，模型只会在美学上越走越远，而在「世界模型」这个真正的目标上原地踏步。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>VBench 系列本身建立了「把评测解耦成多个能力维度」这一范式，可解释性远好于 FID/IS/FVD 这类单一分布距离指标。它的局限不是方法错误，而是覆盖面：表 1 明确列出 VBench 只覆盖 Frame Wise、Temp Cons、Simp Pmpt 三项，全部落在表层。</p><p>针对内在能力的专项基准已经出现，但每个都只覆盖一角。T2V-CompBench 测组合性（动作、空间关系、属性绑定），PhyGenBench 用 VLM 测物理定律理解，StoryEval 靠聚合两个 VLM 的回答测叙事能力。这三者互相不通、prompt 体系各异、评测流水线各异，无法给出一张跨能力的完整画像。</p><p>更深一层的困难在于评测器本身。内在真实性需要评测模型具备复杂场景理解、常识推理与物理感知，因此不得不依赖 VLM/LLM。但作者在 §V-E 里把 VLM 不胜任的原因说得很清楚：其一是训练数据缺口——用于训练 VLM 的真实视频里根本不存在「手指长了十根」「物体凭空分裂」这类生成视频特有的异常，VLM 从未见过这些模式；其二是能力短板——VLM 在物体计数与 3D 理解上本来就弱。这解释了为什么此前没人做全面的内在真实性基准：不是没想到，而是缺一个可靠的裁判。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从一个可观测的事实出发：头部模型在 VBench 上的分差已经小到无法排序，但人眼一看就能挑出毛病。这意味着「人能判断而指标不能」的那部分能力，正是下一代基准应该测的东西。</p><p>接下来的问题是怎么测。最直接的想法是把整段视频丢给最强的 VLM，问「这段视频合理吗」。这个方案会失败，原因可以从两个方向推出来：一是 VLM 在长视频上的点对点总结容易出错（作者在 Complex Plot 一节明确提到 VLM 在分点编号上会出错，需要额外用 LLM 后处理纠正）；二是 VLM 对生成视频特有的异常完全没有先验。</p><p>于是产生了一个自然的分工判断：<strong>哪些能力可以拆解成 VLM 能可靠回答的表层问题，就用问答；哪些能力涉及真实数据里不存在的异常，就必须训专才。</strong> 前者进一步分成两种——单一显著概念可以直接多问几个冗余问题（Video-Based Multi-QA），复杂或微妙的场景则先让 VLM 描述、再让 LLM 与参考答案比对（Text Description Alignment），因为 VLM 的描述能力强于推理能力，而 LLM 的推理能力强于视觉能力，把两者解耦比让一个模型端到端判断更可靠。后者就是 Human Anatomy 与 Instance Preservation 两个专才检测器。</p><p>最后一步是防御性设计：预过滤（先确认人数正确再判断人际交互，先确认初始状态符合 prompt 再判断状态变化）与冗余提问，用来压住 VLM 的幻觉。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>表层真实性是关于像素的，内在真实性是关于因果与结构的，二者需要完全不同的裁判。凡是能被拆成「VLM 睁眼就能看出来的若干个是非题」的，就用冗余问答堆出可靠性；凡是需要跨帧因果推理的，就让 VLM 只负责描述、LLM 负责判断；凡是真实视频里压根不存在（因而 VLM 从未学过）的异常，就必须自己标数据训一个专才。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 Physics 大类下的 Mechanics 维度为例，走一遍完整链路。</p><ul><li><strong>Prompt 构造</strong>：每个维度约 70 条 prompt，刻意做解耦设计（例如 Dynamic Spatial Relationship 只允许一个实体移动，避免多物体交互能力混入）。Mechanics 覆盖重力、浮力、应力等。关键改进在于，不像 PhyGenBench 那样用「液体行为符合微重力环境」这类术语描述，而是用 GPT-4o 把物理现象翻译成<strong>可视化的表观结果</strong>——「液体飘浮，形成团块」。这些描述基于 prompt 事先生成、评测时固定，不影响可复现性。</li><li><strong>视频生成</strong>：四个模型（HunyuanVideo、CogVideoX-1.5-5B、Sora-480p、Kling 1.6）按各自默认配置采样。除 Sora 外，其余三个统一套用改自 CogVideoX 的 Prompt Refiner。</li><li><strong>预过滤</strong>：先检查生成视频的初始状态是否符合 prompt，不符合的直接排除，保证测的是状态变化而非初始条件。</li><li><strong>评分</strong>：用 LLaVA-Video-7B 做多问答，问题冗余设计，按维度约定取平均或全对才计分。</li></ul><p>其他维度的关键实现差异值得单列：</p><ul><li><strong>Human Anatomy</strong>：用 YOLO-World 在每帧检测人体，再检测手与脸，三个基于 ViT-base 的二分类器（人体/手/脸）各自判异常，任一判异常则该人实例被标记；最终分数是未被标记帧的比例。训练数据约 1000 条真实动作视频的正样本 + 用 CogVideo 与 HunyuanVideo 生成的约 1000 条视频经人工精标的负样本，另从 HumanRefiner 补充负样本，共 15 万条帧级标注。</li><li><strong>Identity Consistency</strong>：RetinaFace 检测 + ArcFace 相似度，以首帧为锚，排除多人或无人的时段，且场景切换后仍判是否同一人。</li><li><strong>Diversity</strong>：同一 prompt 采 20 段视频，用 VGG-19 特征算风格与内容的样本间差异。</li><li><strong>Multi-View Consistency</strong>：无 3D 真值，改用 SIFT + FLANN + RANSAC 的特征匹配稳定性，并用 RAFT 估计相机运动速度来调整匹配的帧间隔，避免运动越快分越低的系统偏差。</li><li><strong>Instance Preservation</strong>：基于 Qwen2.5-VL-3B-Instruct 做 LoRA 微调的 clip 级异常检测器，因为实体的合并/分裂发生在相邻帧之间，单帧看都正常。所有 clip 全正常才得 1 分。</li><li><strong>Camera Motion</strong>：把 VBench++ 的相机运动分类扩到九种（新增 Orbit 与斜向航拍推移），用 CoTracker-v2 做点跟踪加启发式规则判定。</li></ul><p><strong>人类对齐标注</strong>：四个模型两两配对共 6 对，每条 prompt 采 5 组，标注者选偏好，平局各得 0.5，算模型级 win ratio。20% 随机抽检，要求 95% 通过率。总计 18 名标注者、284 人时。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>两条评测范式的形式化：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">Answer</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord text"><span class="mord">LLM</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord text"><span class="mord">VLM</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span></span></span> 是生成视频，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 是文本 prompt 或人工构造的参考答案，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 分别是给 VLM 与 LLM 的系统提示。LLM 输出二值判断，离散化为 0/1。这个式子的 intuition 是把「看」与「想」拆开：VLM 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的约束下只描述某个特定侧面（例如只描述人际交互），LLM 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的约束下只做文本层面的语义匹配。</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">Answer</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">VQA</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8747em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mclose">)</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 是一组互补且部分冗余的问题。冗余的作用可以这样理解：若单题准确率为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span>、错误近似独立，则「全对才算通过」的假阳性率约为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0913em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span></span></span></span></span></span></span> 量级，代价是假阴性率上升。作者按维度选择「取均值」或「全对才给分」，实质是在这两类错误间做偏好选择，但论文没有报告任何单题准确率，因此这一权衡的量化效果无法核验。</p><p>值得指出的是一处措辞不严：§V-E 声称「VBench-2.0 adopts a non-fine-tuning approach」，理由是微调过的评测器容易过拟合到生成数据、难以泛化到更长视频。但 Human Anatomy 的三个 ViT 分类器与 Instance Preservation 的 Qwen2.5-VL LoRA 都是实打实微调出来的。准确的表述应是「通才路径不微调，专才路径必须微调」，论文在 §III 里其实是这么做的，只是 §V-E 的概括过宽。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：18 个维度能不能把四个头部模型区分开？</strong> 表 II 给出全部数值，区分度确实存在且差异巨大。Camera Motion 上 Kling 1.6 拿 61.73%，其余三家在 27.16%–33.95%；Multi-View Consistency 上 Kling 64.38% / Sora 58.22%，而 CogVideoX-1.5 只有 21.79%；Human Anatomy 上 CogVideoX-1.5 的 59.72% 明显落后于其余三家的 86%–89%。</p><p><strong>问题二：模型的能力画像是什么？</strong> Sora 在 Human Fidelity（Clothes 98.15、Identity 78.57）与 Creativity（Composition 53.65、Diversity 67.48）上领先，但在 Controllability、Physics、Commonsense 上落后（Dynamic Attribute 只有 8.06%，Motion Order 15.15%，均为四家最低）。Kling 全面均衡且在相机相关维度突出。CogVideoX-1.5 在 State Change 三项（Mechanics 80.80、Material 83.19、Thermotics 67.13）全部第一——但同属 Physics 大类的 Multi-View Consistency 却是全表最低的 21.79%，所以「CogVideoX 强于 Physics」这个概括只在状态变化子类上成立，几何子类恰恰相反。HunyuanVideo 在多数维度偏弱但人体相关维度（Human Anatomy 88.58）最强。</p><p><strong>问题三：哪些能力是全行业的短板？</strong> 两个。其一是 Complex Plot（15.33%–20.00%）与 Complex Landscape（9.78%–11.21%），后者四家全部挤在 10% 附近，几乎没有区分度——作者归因于当前基座模型只能生成 10 秒以内的单镜头视频，承载不了多场景叙事。其二更出人意料：Dynamic Spatial Relationship 与 Dynamic Attribute 上所有模型都在 19%–24%（Sora 的 Dynamic Attribute 甚至只有 8.06%），即「让一个物体从左边跑到前面」或「让树叶从红变绿」这种极简单的指令，模型有约 80% 的概率做不到。作者的解释是视频标注流水线没有刻意描述属性与位置随时间的演化，因而模型从未学过这类监督。</p><p><strong>问题四：自动评测与人类判断是否一致？</strong> 表 IV 逐维度给出「VBench-2.0 win ratio / 人类 win ratio」，报告的相关系数在 87.97%–99.31% 之间。</p><p><strong>问题五：Prompt Refiner 的作用边界？</strong> 三个观察：Creativity 与 Controllability 之间存在权衡（Sora 创造性强但可控性弱，另外三家相反，而后三家恰好都用了统一的 Prompt Refiner）；Physics 维度上除 Sora 外都表现尚可，暗示物理合理性可以靠提示词工程部分补偿，真正的困难可能在于精确的视频-文本对齐而非物理推理本身；而 Human Fidelity、Camera Motion、Geometry、Commonsense 这类依赖模型内在先验的维度，换提示词优化器没有一致趋势。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：视频生成的表层指标已经饱和，下一代基准必须测内在真实性——物理定律、常识、解剖正确性与组合完整性；VBench-2.0 用五大类 18 维、通才 VLM/LLM 加专才异常检测器的混合流水线实现了这一点，并配以预过滤与冗余提问来压制幻觉；四个头部模型呈现出清晰且互不相同的能力画像，说明这套指标确实有区分度；全行业的共同短板是复杂叙事（10%–20%）与简单动态可控性（约 80% 失败率），后者被归因于视频标注流水线缺少时序演化描述；作者明确建议 VBench 与 VBench-2.0 并用，因为表层与内在是两根不可互相替代的支柱。</p><p><strong>3 句话版</strong>：模型看起来越来越真，但仍不遵守物理与常识，而旧指标测不出这一点。VBench-2.0 把 18 个内在能力维度拆开来测，并为 VLM 不胜任的维度训了专才检测器。最反直觉的发现是「让物体变个色」这种简单指令的失败率高达 80%。</p><p><strong>1 句话版</strong>：视频评测的下一站不是画得更好看，而是画得更讲道理，而当前模型在最简单的动态可控性上仍然大面积失败。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>四个模型上的模型级 win ratio 相关性，足以证明每个维度的评测方法与人类判断一致。</strong></p><p>这是整套基准的合法性基础——18 个维度用了 18 套不同的、相当复杂的启发式流水线（YOLO-World + ViT 三分类器、SIFT/FLANN/RANSAC + RAFT 校正、CoTracker 加人工规则、LoRA 微调的 clip 级检测器），每一套都有大量未被消融的设计选择，唯一的整体质量保证就是与人类 win ratio 的相关性。</p><p>问题在于统计功效。相关性是在<strong>四个模型</strong>上计算的，也就是每个维度只有四个数据点。Spearman 相关在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> 时，取值只能落在极少数离散值上，达到 0.9 以上并不需要多强的证据；而报告出的 87.97%–99.31% 这个区间的下限，在四点样本下几乎无法与随机区分。更进一步，四个模型在多数维度上的分差很大（例如 Camera Motion 上 Kling 61.73 vs 其余约 30），把它们排对顺序是很容易的任务，这与「能否在两段相近质量的视频之间做出正确判断」完全不是一回事。</p><p>论文缺的证据很具体：没有实例级（单条视频）的人机一致性，没有标注者间一致性统计（Cohen&#39;s κ 或 Krippendorff&#39;s α），也没有任何维度的评测器单独准确率。20% 抽检 95% 通过率保证的是标注执行质量，不是评测器质量。</p><p>一个佐证这个担心的现象是 Complex Landscape：四个模型全部落在 9.78%–11.21%，极差仅 1.43 个百分点。在这样的区间上计算模型级 win ratio 相关性，噪声几乎必然主导。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要复现全部 18 维：</p><ol><li>选三个成本最低且互补的维度：Dynamic Attribute（纯 VQA）、Motion Order（VLM+LLM）、Human Anatomy（专才检测器）。</li><li>用两个开源模型（CogVideoX-1.5 与 HunyuanVideo）各生成 70×3 条视频。</li><li>关键补充实验——对每个维度随机抽 100 条视频做<strong>实例级</strong>人工标注（而非模型级偏好），计算评测器的准确率、精确率与召回率。</li><li>同时跑一组负控制：把真实视频（例如从 Pexels 采集的对应场景片段）喂进同一套流水线，看假阳性率。</li></ol><p>判据：若三个维度的实例级准确率都在 80% 以上、真实视频的假阳性率低于 10%，则评测器可信；若 Dynamic Attribute 的准确率显著低于另外两个，那么「80% 失败率」这个头条结论就需要重新解释——可能有相当比例是评测器漏判而非模型失败。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的替代解释是：<strong>Dynamic Attribute / Dynamic Spatial Relationship 的极低分数，主要度量的是 VLM 的跨时序判别能力，而非视频模型的可控性。</strong> 这两个维度的问法是「初始时河水是否主要为蓝色 / 最终是否主要为棕色 / 颜色是否变化」三连问，要求 LLaVA-Video-7B 在一段视频内做时间定位并比较。这恰好落在作者自己在 §V-E 承认的 VLM 短板区（计数与 3D 理解弱，且从未见过生成视频的异常模式）。若 VLM 本身在这类问题上准确率只有六七成，观测到的 20% 得分就无法归因给生成模型。</p><p>设计一个能证伪的实验：构造一个<strong>真值可控的对照集</strong>。用真实拍摄或程序渲染的方式，造 70 段确实发生了指定属性变化的视频（例如实拍一片叶子被喷漆从红变绿，或用 Blender 渲染物体位移），把它们喂进同一套 Dynamic Attribute 流水线。若这批「保证正确」的视频得分同样只有 20%–30%，则该维度的分数几乎全部由评测器噪声构成，全行业 80% 失败率的结论直接失效；若得分接近 100%，则该结论稳固，且顺带给出了评测器的准确率上界。</p><p>第二条攻击线针对跨模型比较的公平性：四个模型中只有 Sora 未使用统一的 Prompt Refiner（作者的理由是 Sora 可能内置了改写器，加上外部改写反而变差），而 Sora 同时是 480p 版本、分辨率与帧率都与其余三家不同（480×854/30fps vs 720×1280/24fps 与 768×1360/16fps）。于是「Sora 可控性弱、创造性强」这一画像至少有两个混淆项：不同的提示词处理路径，以及不同的分辨率。论文自己在 §V-C 也承认「另一种可能是 Prompt Refiner 通过细化文本提升了可控性而牺牲了多样性」——这实际上已经把结论从「模型特性」削弱成了「流水线差异」，但表 II 与图 2 的呈现方式仍然是模型级比较。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：VBench-2.0 的 18 个维度是<strong>人工设计的分类学</strong>，每个维度配一套人工设计的流水线。这条路的成本随维度数线性增长，而且天然滞后——新的失败模式出现后，需要有人先注意到、再设计 prompt、再设计评测流水线。作者在 §V-E 里也提出了「训练一个统一的 clip 级异常检测大模型」的方向，但那仍然是在既有异常类型上做合并。</p><p><strong>新的 framing</strong>：把内在真实性评测从「按人工分类学逐项打分」重述为「<strong>估计生成视频相对真实视频分布的可判别性，并对判别信号做归因</strong>」。具体地，训练一个真实/生成的判别器，然后不是用它的准确率作为指标（那退回到 FVD 的老路），而是用可解释性方法把判别信号定位到时空区域与语义概念上，让<strong>失败模式的分类学从数据里自动涌现</strong>，而不是由人预先规定。这样做的价值在于：当模型进步到现有 18 维全部饱和时，这套机制能自动指出新的短板在哪里；而且它天然给出实例级信号，正好补上 §9 指出的证据缺口。</p><p><strong>可借鉴的相邻领域工具</strong>：深度伪造检测领域已经有成熟的「判别 + 定位」框架；机制可解释性里的稀疏自编码器（SAE）被用来从表示中抽取人类可命名的概念，可以直接作用在判别器的中间层上；因果表征学习提供了把判别信号归因到干预变量的语言。</p><p><strong>第一个实验</strong>：用 VBench-2.0 已有的 18 维标注数据作为验证集。先在「真实视频 vs 四个模型生成视频」上训一个 clip 级判别器，再用 SAE 在其中间层抽取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个概念方向，人工命名后计算每个概念的激活与 18 个已知维度分数的相关性。三个预期结果都有信息量：(a) 若某些自动发现的概念与已知维度高度对应，说明该管线有效；(b) 若存在高判别力但不对应任何已知维度的概念，那就是分类学的盲区，直接构成 VBench-3.0 的候选维度；(c) 若判别器主要靠低层纹理统计（而非语义概念）就能区分真假，则说明当前生成视频离真实分布的距离仍主要由表层因素主导，那么「表层已饱和」这一全文前提本身需要修正。</p>',60)])])}const d=a(p,[["render",i]]);export{g as __pageData,d as default};
